"use client";

import Image from "next/image";
import Link from "next/link";
import { useEffect, useState } from "react";
import axios from "axios";

type ReadProductTierOptionDto = { id: number; name: string };
type ReadProductTierDto = {
  id: number;
  name: string;
  options: ReadProductTierOptionDto[];
  hasImages?: boolean;
};
type ReadProductVariationOptionDto = { tierId: number; optionId: number };
type ReadProductVariationDto = {
  id: number;
  price: number;
  stock: number;
  optionCombination: ReadProductVariationOptionDto[];
};
type ReadProductImageDto = { id: number; url: string; sort?: number };
type ReadProductDto = {
  productId: number;
  productName: string;
  description?: string;
  images: ReadProductImageDto[];
  tiers: ReadProductTierDto[];
  variations: ReadProductVariationDto[];
};

export type SellerVariation = {
  id: number;
  name: string;
  price: number;
  stock: number;
};

export type SellerProduct = {
  id: number;
  name: string;
  thumbnail: string;
  variations: SellerVariation[];
};

const formatPrice = (value: number) =>
  new Intl.NumberFormat("vi-VN", {
    style: "currency",
    currency: "VND",
    maximumFractionDigits: 0,
  }).format(value);

function buildVariationName(
  variation: ReadProductVariationDto,
  tiers: ReadProductTierDto[],
): string {
  if (!variation.optionCombination?.length) return "Mặc định";
  const names = variation.optionCombination.map((combo) => {
    const tier = tiers.find((t) => t.id === combo.tierId);
    const option = tier?.options?.find((o) => o.id === combo.optionId);
    return option?.name ?? "";
  });
  return names.filter(Boolean).join(" / ") || "Mặc định";
}

/** Build URL cho ảnh: backend serve tại http://localhost:9090/static/{path} (vd. products/2026/02/11/xxx.jpg) */
function imagePathToUrl(path: string): string {
  if (!path) return "";
  if (path.startsWith("http")) return path;
  const normalized = path.startsWith("/") ? path.slice(1) : path;
  return `/api/static/${normalized}`;
}

function mapToSellerProduct(dto: ReadProductDto): SellerProduct {
  const firstImage =
    dto.images?.length > 0
      ? [...dto.images].sort((a, b) => (a.sort ?? 0) - (b.sort ?? 0))[0]
      : null;
  const thumbnail = firstImage?.url ?? "";
  const variations: SellerVariation[] = (dto.variations ?? []).map((v) => ({
    id: v.id,
    name: buildVariationName(v, dto.tiers ?? []),
    price: Number(v.price) ?? 0,
    stock: v.stock ?? 0,
  }));
  return {
    id: dto.productId,
    name: dto.productName,
    thumbnail: imagePathToUrl(thumbnail),
    variations,
  };
}

