// Khớp với server: GET /product/list?shopId=1 (ProductController.listProductsByShopId)
const SHOP_ID = 1; // TODO: lấy từ context/auth khi có
const PRODUCT_LIST_URL = `/api/product/list?shopId=${SHOP_ID}`;

export default function ProductsPage() {
  const [products, setProducts] = useState<SellerProduct[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    axios
      .get<ReadProductDto[]>(PRODUCT_LIST_URL)
      .then((res) => {
        if (cancelled) return;
        const data = res.data;
        setProducts(
          Array.isArray(data) ? data.map(mapToSellerProduct) : [],
        );
      })
      .catch((err) => {
        if (!cancelled) {
          const message = axios.isAxiosError(err)
            ? err.response?.data != null
              ? String(err.response.data)
              : err.response?.status === 404
                ? "Không tìm thấy API danh sách sản phẩm. Kiểm tra backend có endpoint GET /product/list?shopId=..."
                : err.message
            : "Không tải được danh sách sản phẩm.";
          setError(message);
          setProducts([]);
        }
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  if (loading) {
    return (
      <div className="mx-auto flex min-h-screen max-w-6xl flex-col gap-6 px-4 py-6">
        <header>
          <h1 className="text-2xl font-semibold tracking-tight text-[var(--foreground)]">
            Tất cả sản phẩm
          </h1>
          <p className="mt-1 text-sm text-[var(--muted-foreground)]">
            Đang tải...
          </p>
        </header>
      </div>
    );
  }

  if (error) {
    return (
      <div className="mx-auto flex min-h-screen max-w-6xl flex-col gap-6 px-4 py-6">
        <header>
          <h1 className="text-2xl font-semibold tracking-tight text-[var(--foreground)]">
            Tất cả sản phẩm
          </h1>
          <p className="mt-1 text-sm text-red-600">{error}</p>
        </header>
      </div>
    );
  }

  return <AllProductsPagePanel products={products} />;
}
